package ui

// AdminNovaCSS defines the "Nova" admin visual theme mode: a shadcn/Vercel
// dashboard-inspired token palette (indigo brand, slate neutrals, soft
// low-opacity shadows) layered the same way as AdminShadcnCSS and
// AdminWorkbenchCSS (ADR-0041), reusing the shared semantic token names from
// AdminCSS (ADR-0053). See docs/architecture/0335-admin-nova-theme-mode.md.
const AdminNovaCSS = `html[data-ui-theme="nova"]{--bg:#f8fafc;--surface:#ffffff;--surface-raised:#ffffff;--surface-hover:#f1f5f9;--bg-subtle:#f1f5f9;--ink:#0f172a;--ink-secondary:#334155;--muted:#64748b;--line:#e2e8f0;--line-light:#cbd5e1;--brand:#4f46e5;--brand-hover:#4338ca;--brand-light:#6366f1;--brand-subtle:#eef2ff;--brand-glow:rgba(79,70,229,.18);--green:#16a34a;--green-subtle:#f0fdf4;--red:#dc2626;--red-subtle:#fef2f2;--amber:#d97706;--radius-xs:10px;--radius-sm:12px;--radius-md:14px;--radius-lg:20px;--radius-xl:28px;--shadow-xs:none;--shadow-sm:0 1px 2px rgba(15,23,42,.06);--shadow-md:0 4px 12px rgba(15,23,42,.08);--shadow-lg:0 12px 28px rgba(15,23,42,.12);--card-highlight:0 1px 2px rgba(15,23,42,.04),0 1px 3px rgba(15,23,42,.08)}html[data-ui-theme="nova"][data-theme="dark"]{--bg:#0b1220;--surface:#0f172a;--surface-raised:#131f36;--surface-hover:#1e293b;--bg-subtle:#111827;--ink:#f1f5f9;--ink-secondary:#cbd5e1;--muted:#94a3b8;--line:#1e293b;--line-light:#334155;--brand:#818cf8;--brand-hover:#a5b4fc;--brand-light:#818cf8;--brand-subtle:#1e1b4b;--brand-glow:rgba(129,140,248,.24);--green:#4ade80;--green-subtle:#052e16;--red:#f87171;--red-subtle:#450a0a;--amber:#fbbf24;--shadow-xs:none;--shadow-sm:0 1px 2px rgba(0,0,0,.4);--shadow-md:0 4px 14px rgba(0,0,0,.45);--shadow-lg:0 12px 28px rgba(0,0,0,.6);--card-highlight:0 1px 2px rgba(0,0,0,.3),0 2px 8px rgba(0,0,0,.35)}html[data-ui-theme="nova"] body{background:var(--bg);color:var(--ink)}html[data-ui-theme="nova"] .studio-sidebar{background:var(--surface);border-right:1px solid var(--line);box-shadow:none}html[data-ui-theme="nova"] .sidebar-header{border-bottom:1px solid var(--line);background:transparent}html[data-ui-theme="nova"] .sidebar-bottom{border-top:1px solid var(--line);background:var(--bg-subtle)}html[data-ui-theme="nova"] .studio-brand{color:var(--ink)}html[data-ui-theme="nova"] .sidebar-section-label{color:var(--muted)}html[data-ui-theme="nova"] .nav-item{color:var(--ink-secondary);border-radius:var(--radius-sm)}html[data-ui-theme="nova"] .brand-text small{color:var(--muted)}html[data-ui-theme="nova"] .brand-logo-mark{background:var(--brand);color:#fff;border-radius:var(--radius-md);box-shadow:none}html[data-ui-theme="nova"] .nav-item:hover{background:var(--bg-subtle);color:var(--ink);border-color:transparent}html[data-ui-theme="nova"] .nav-item.is-active{background:var(--brand-subtle)!important;color:var(--brand-light)!important;border-color:transparent!important;box-shadow:none!important;font-weight:600!important}html[data-ui-theme="nova"] .studio-topbar{background:var(--surface);border-bottom:1px solid var(--line);box-shadow:none}html[data-ui-theme="nova"] .studio-card,html[data-ui-theme="nova"] .dashboard-kpi,html[data-ui-theme="nova"] .dashboard-card,html[data-ui-theme="nova"] .collection-tile,html[data-ui-theme="nova"] .tool-tile,html[data-ui-theme="nova"] .meta-item,html[data-ui-theme="nova"] .report-info-card{background:var(--surface);border-color:var(--line);box-shadow:var(--card-highlight)}html[data-ui-theme="nova"] .studio-card,html[data-ui-theme="nova"] .dashboard-kpi,html[data-ui-theme="nova"] .dashboard-card,html[data-ui-theme="nova"] .report-info-card{border-radius:var(--radius-lg)}html[data-ui-theme="nova"] .studio-form button:not(.button-quiet):not(.button-secondary),html[data-ui-theme="nova"] .button:not(.button-quiet):not(.button-secondary),html[data-ui-theme="nova"] .studio-card button:not(.button-quiet):not(.button-secondary){border-radius:var(--radius-md);background:var(--brand);color:#fff;box-shadow:none}html[data-ui-theme="nova"] .studio-form button:not(.button-quiet):not(.button-secondary):hover,html[data-ui-theme="nova"] .button:not(.button-quiet):not(.button-secondary):hover,html[data-ui-theme="nova"] .studio-card button:not(.button-quiet):not(.button-secondary):hover{background:var(--brand-hover);color:#fff;transform:none;box-shadow:none}html[data-ui-theme="nova"] .button-quiet,html[data-ui-theme="nova"] .button-secondary{border-radius:var(--radius-md);background:var(--bg-subtle)!important;color:var(--ink)!important;border:1px solid var(--line)!important;box-shadow:none}html[data-ui-theme="nova"] .button-quiet:hover,html[data-ui-theme="nova"] .button-secondary:hover{background:var(--surface-hover)!important;color:var(--brand-light)!important;border-color:var(--line-light)!important}html[data-ui-theme="nova"][data-theme="dark"] .button-quiet,html[data-ui-theme="nova"][data-theme="dark"] .button-secondary{background:#131f36!important;color:#cbd5e1!important;border:1px solid #1e293b!important}html[data-ui-theme="nova"][data-theme="dark"] .button-quiet:hover,html[data-ui-theme="nova"][data-theme="dark"] .button-secondary:hover{background:#1e293b!important;color:#f8fafc!important;border-color:#334155!important}html[data-ui-theme="nova"] .studio-search{border-color:var(--line);border-radius:var(--radius-md);background:var(--bg-subtle);box-shadow:none}
html[data-ui-theme="nova"] .studio-search:hover{border-color:var(--line-light);background:var(--surface)}
html[data-ui-theme="nova"] .studio-search:focus-within{border-color:var(--brand);background:var(--surface);box-shadow:0 0 0 1px var(--brand)}
html[data-ui-theme="nova"] .theme-toggle-btn,html[data-ui-theme="nova"] .studio-user{border-color:var(--line);border-radius:var(--radius-md);background:var(--surface);box-shadow:none}input,select,textarea,.studio-form input,.studio-form select,.studio-form textarea,.studio-card input,.studio-card select,.studio-card textarea{border-radius:var(--radius-md);background:var(--surface);border:1px solid var(--line);color:var(--ink);font:inherit;font-size:.82rem;min-height:32px;box-sizing:border-box}html[data-ui-theme="nova"] input,html[data-ui-theme="nova"] select,html[data-ui-theme="nova"] textarea,html[data-ui-theme="nova"] .studio-form input,html[data-ui-theme="nova"] .studio-form select,html[data-ui-theme="nova"] .studio-form textarea,html[data-ui-theme="nova"] .studio-card input,html[data-ui-theme="nova"] .studio-card select,html[data-ui-theme="nova"] .studio-card textarea{border-radius:var(--radius-md);background:var(--surface);border-color:var(--line);color:var(--ink)}html[data-theme="dark"] input,html[data-theme="dark"] select,html[data-theme="dark"] textarea{background:var(--bg-subtle);border-color:var(--line);color:var(--ink)}input:focus,select:focus,textarea:focus,html[data-ui-theme="nova"] input:focus,html[data-ui-theme="nova"] select:focus,html[data-ui-theme="nova"] textarea:focus,html[data-ui-theme="nova"] .studio-form input:focus,html[data-ui-theme="nova"] .studio-form select:focus,html[data-ui-theme="nova"] .studio-form textarea:focus,html[data-ui-theme="nova"] .studio-card input:focus,html[data-ui-theme="nova"] .studio-card select:focus,html[data-ui-theme="nova"] .studio-card textarea:focus{border-color:var(--brand);box-shadow:0 0 0 2px var(--brand-glow)}html[data-ui-theme="nova"] .studio-heading h1,html[data-ui-theme="nova"] .dashboard-welcome h2{letter-spacing:-.03em}html[data-ui-theme="nova"] .studio-badge-status{border-color:var(--line);background:var(--bg-subtle);color:var(--ink-secondary);border-radius:999px}html[data-ui-theme="nova"] ::selection{background:var(--brand);color:#fff}html[data-ui-theme="nova"] :focus-visible{outline:2px solid var(--brand);outline-offset:2px}`

// AdminNovaDensityCSS mirrors AdminWorkbenchDensityCSS's layout density rules,
// re-scoped to the Nova mode.
const AdminNovaDensityCSS = `html[data-ui-theme="nova"] .studio-content{max-width:1600px}html[data-ui-theme="nova"] .studio-card,html[data-ui-theme="nova"] .dashboard-card{padding:20px 22px}html[data-ui-theme="nova"] .studio-card h2,html[data-ui-theme="nova"] .dashboard-card h2{font-size:1.02rem;letter-spacing:-.01em}html[data-ui-theme="nova"] .studio-card th{background:var(--bg-subtle);color:var(--muted);font-size:.68rem;letter-spacing:.06em;text-transform:uppercase}html[data-ui-theme="nova"] .studio-card td{font-size:.8rem}html[data-ui-theme="nova"] .nav-item{min-height:38px;padding:9px 12px;font-size:.84rem;border-radius:var(--radius-md)}html[data-ui-theme="nova"] .sidebar-section-label{margin:12px 10px 4px;font-size:.64rem;letter-spacing:.08em}html[data-ui-theme="nova"] .studio-search{min-height:38px;height:38px;font-size:.84rem;border-radius:var(--radius-lg)}html[data-ui-theme="nova"] .button,html[data-ui-theme="nova"] .studio-form button{min-height:38px;height:38px;padding:0 18px;font-size:.82rem;font-weight:600;border-radius:var(--radius-md)}html[data-ui-theme="nova"] .button-quiet,html[data-ui-theme="nova"] .button-secondary{min-height:38px;height:38px;padding:0 18px;font-size:.82rem;border-radius:var(--radius-md);color:var(--ink)!important}html[data-ui-theme="nova"][data-theme="dark"] .button-quiet,html[data-ui-theme="nova"][data-theme="dark"] .button-secondary{color:#cbd5e1!important}html[data-ui-theme="nova"] .studio-alert{border:1px solid var(--red);border-radius:var(--radius-md)}html[data-ui-theme="nova"] .studio-form label{font-size:.76rem;font-weight:600}html[data-ui-theme="nova"] .studio-form input,html[data-ui-theme="nova"] .studio-form select,html[data-ui-theme="nova"] .studio-form textarea{font-size:.82rem;border-radius:var(--radius-md)}`

// AdminNovaTypeCSS mirrors AdminWorkbenchTypeCSS's font-family rules,
// re-scoped to the Nova mode.
const AdminNovaTypeCSS = `html[data-ui-theme="nova"] body,html[data-ui-theme="nova"] button,html[data-ui-theme="nova"] input,html[data-ui-theme="nova"] select,html[data-ui-theme="nova"] textarea{font-family:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI Variable","Segoe UI",sans-serif!important;letter-spacing:-.011em}html[data-ui-theme="nova"] code,html[data-ui-theme="nova"] kbd,html[data-ui-theme="nova"] pre{font-family:"JetBrains Mono","IBM Plex Mono","SFMono-Regular",Consolas,monospace!important}`

// AdminNovaDashboardCSS mirrors AdminWorkbenchDashboardCSS's dashboard layout
// rules, re-scoped to the Nova mode. The dashboard markup itself
// (internal/ui/admin_workbench.go's html/template) is mode-agnostic, so this
// is CSS-only re-skinning; no Go template changes are required. The
// wb-rise/wb-pulse keyframes are intentionally not redefined here: they are
// already declared once in AdminWorkbenchDashboardCSS, which is always
// concatenated into the page regardless of the active mode.
const AdminNovaDashboardCSS = `html[data-ui-theme="nova"] .dashboard-welcome-panel{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:14px;padding:14px 18px;border:1px solid var(--line);border-radius:var(--radius-lg);background:var(--surface);box-shadow:none;animation:wb-rise .3s cubic-bezier(.16,1,.3,1) both}html[data-ui-theme="nova"] .dashboard-welcome-panel h2{margin:4px 0 2px;font-size:1.25rem;letter-spacing:-.03em}html[data-ui-theme="nova"] .dashboard-welcome-panel p{margin:0;color:var(--ink-secondary);font-size:.8rem}html[data-ui-theme="nova"] .dashboard-status-line{display:inline-flex;align-items:center;gap:5px;color:var(--brand);font-size:.66rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase}html[data-ui-theme="nova"] .dashboard-status-line i{width:5px;height:5px;border-radius:50%;background:var(--green);box-shadow:0 0 0 2px var(--green-subtle);animation:wb-pulse 2s ease-in-out infinite}html[data-ui-theme="nova"] .dashboard-welcome-actions{display:flex;align-items:center;gap:6px;flex-shrink:0}html[data-ui-theme="nova"] .dashboard-welcome-actions .button{display:inline-flex;align-items:center;gap:5px;width:auto;min-height:30px;height:30px;border-radius:var(--radius-md)}html[data-ui-theme="nova"] .dashboard-overview{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:14px}html[data-ui-theme="nova"] .dashboard-stat{position:relative;min-height:86px;padding:10px 12px;overflow:hidden;border:1px solid var(--line);border-radius:var(--radius-md);background:var(--surface);box-shadow:none;animation:wb-rise .3s cubic-bezier(.16,1,.3,1) both}html[data-ui-theme="nova"] .dashboard-stat:nth-child(2){animation-delay:30ms}html[data-ui-theme="nova"] .dashboard-stat:nth-child(3){animation-delay:60ms}html[data-ui-theme="nova"] .dashboard-stat:nth-child(4){animation-delay:90ms}html[data-ui-theme="nova"] .dashboard-stat-accent{border-color:var(--brand)}html[data-ui-theme="nova"] .dashboard-stat-label{display:block;color:var(--muted);font-size:.66rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase}html[data-ui-theme="nova"] .dashboard-stat strong{display:block;margin:4px 0 1px;color:var(--ink);font:700 1.3rem/1 var(--font-mono);letter-spacing:-.03em}html[data-ui-theme="nova"] .dashboard-stat strong em{font-size:.75rem;font-style:normal;letter-spacing:0}html[data-ui-theme="nova"] .dashboard-stat small{display:block;color:var(--muted);font-size:.66rem}html[data-ui-theme="nova"] .dashboard-stat-glyph{position:absolute;right:10px;top:10px;display:grid;place-items:center;width:24px;height:24px;border-radius:var(--radius-sm);background:var(--bg-subtle);color:var(--brand);border:1px solid var(--line)}html[data-ui-theme="nova"] .dashboard-stat-glyph svg{width:13px;height:13px}html[data-ui-theme="nova"] .dashboard-stat.is-alert{border-color:var(--red)}html[data-ui-theme="nova"] .dashboard-stat.is-alert .dashboard-stat-glyph{background:var(--red-subtle);color:var(--red)}html[data-ui-theme="nova"] .dashboard-workspace-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr);gap:14px}html[data-ui-theme="nova"] .dashboard-side-stack{display:grid;gap:14px;align-content:start}html[data-ui-theme="nova"] .dashboard-section-kicker{display:block;margin-bottom:3px;color:var(--muted);font-size:.64rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase}html[data-ui-theme="nova"] .dashboard-card-head{align-items:flex-start}html[data-ui-theme="nova"] .dashboard-card-head h2{margin:0}html[data-ui-theme="nova"] .dashboard-card-head .text-link{display:inline-flex;align-items:center;gap:4px;font-size:.74rem}html[data-ui-theme="nova"] .collection-grid{gap:6px}html[data-ui-theme="nova"] .collection-tile{min-height:52px;border-radius:var(--radius-md);background:var(--bg-subtle);border:1px solid var(--line);transition:background .12s ease,border-color .12s ease}html[data-ui-theme="nova"] .collection-tile:hover{background:var(--surface-hover);border-color:var(--brand)}html[data-ui-theme="nova"] .quick-action-list{display:grid;gap:4px}html[data-ui-theme="nova"] .quick-action-list a{display:grid;grid-template-columns:26px minmax(0,1fr) 14px;align-items:center;gap:8px;padding:6px 8px;border-radius:var(--radius-md);color:var(--ink);text-decoration:none;border:1px solid transparent;transition:background .12s ease,border-color .12s ease}html[data-ui-theme="nova"] .quick-action-list a:hover{background:var(--surface-hover);border-color:var(--line)}html[data-ui-theme="nova"] .quick-action-list a>span:first-child{display:grid;place-items:center;width:26px;height:26px;border-radius:var(--radius-sm);background:var(--brand-subtle);border:1px solid var(--line);color:var(--brand)}html[data-ui-theme="nova"] .quick-action-list a svg{width:13px;height:13px}html[data-ui-theme="nova"] .quick-action-list strong,html[data-ui-theme="nova"] .quick-action-list small{display:block}html[data-ui-theme="nova"] .quick-action-list strong{font-size:.76rem}html[data-ui-theme="nova"] .quick-action-list small{margin-top:1px;color:var(--muted);font-size:.66rem}html[data-ui-theme="nova"] .quick-action-list b{color:var(--muted)}html[data-ui-theme="nova"] .dashboard-health dl{display:grid;gap:0;margin:2px 0 10px}html[data-ui-theme="nova"] .dashboard-health dl div{display:flex;justify-content:space-between;gap:10px;padding:6px 0;border-bottom:1px solid var(--line)}html[data-ui-theme="nova"] .dashboard-health dt{color:var(--muted);font-size:.74rem}html[data-ui-theme="nova"] .dashboard-health dd{margin:0;color:var(--ink-secondary);font-size:.74rem;font-weight:700;text-align:right;font-family:var(--font-mono)}html[data-ui-theme="nova"] .dashboard-health-dot{display:inline-flex;align-items:center;gap:5px;color:var(--green);font-size:.68rem;font-weight:700}html[data-ui-theme="nova"] .dashboard-health-dot i{width:5px;height:5px;border-radius:50%;background:var(--green)}html[data-ui-theme="nova"] .dashboard-health .text-link{display:inline-flex;align-items:center;gap:4px;font-size:.74rem}@media(max-width:980px){html[data-ui-theme="nova"] .dashboard-overview{grid-template-columns:repeat(2,minmax(0,1fr))}html[data-ui-theme="nova"] .dashboard-workspace-grid{grid-template-columns:1fr}}@media(max-width:640px){html[data-ui-theme="nova"] .dashboard-welcome-panel{display:grid;align-items:start;padding:12px}.dashboard-welcome-actions{width:100%}html[data-ui-theme="nova"] .dashboard-welcome-actions .button{flex:1;justify-content:center}html[data-ui-theme="nova"] .dashboard-overview{grid-template-columns:1fr 1fr;gap:6px}html[data-ui-theme="nova"] .dashboard-stat{min-height:80px;padding:10px}.dashboard-stat-glyph{display:none!important}}@media(prefers-reduced-motion:reduce){html[data-ui-theme="nova"] .dashboard-welcome-panel,html[data-ui-theme="nova"] .dashboard-stat{animation:none}html[data-ui-theme="nova"] .collection-tile,html[data-ui-theme="nova"] .quick-action-list a{transition:none}}`

// AdminNovaComponentsCSS mirrors AdminWorkbenchComponentsCSS's .wb-* dashboard
// component rules, re-scoped to the Nova mode.
const AdminNovaComponentsCSS = `html[data-ui-theme="nova"] .wb-dashboard{display:grid;gap:16px;max-width:1600px;margin:0 auto}
html[data-ui-theme="nova"] .wb-command-row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding-bottom:12px;border-bottom:1px solid var(--line)}
html[data-ui-theme="nova"] .wb-breadcrumb{display:flex;align-items:center;gap:6px;color:var(--muted);font-size:.76rem;font-weight:600}
html[data-ui-theme="nova"] .wb-scope-badge{display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border-radius:var(--radius-sm);background:var(--bg-subtle);border:1px solid var(--line);color:var(--ink-secondary);font-size:.7rem;font-weight:700;font-family:var(--font-mono)}
html[data-ui-theme="nova"] .wb-scope-badge i{width:5px;height:5px;border-radius:50%;background:var(--brand)}
html[data-ui-theme="nova"] .wb-command-actions{display:flex;align-items:center;gap:8px}
html[data-ui-theme="nova"] .wb-command-actions .button{min-height:32px;height:32px;padding:0 14px;font-size:.78rem;border-radius:var(--radius-md);font-weight:600}
html[data-ui-theme="nova"] .wb-hero{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 20px;border:1px solid var(--line);border-radius:var(--radius-lg);background:linear-gradient(180deg,var(--surface) 0%,var(--bg-subtle) 100%);box-shadow:var(--card-highlight);position:relative;overflow:hidden}
html[data-ui-theme="nova"] .wb-hero-copy{display:flex;flex-direction:column;justify-content:center}
html[data-ui-theme="nova"] .wb-eyebrow{display:inline-flex;align-items:center;gap:6px;color:var(--brand-light);font-size:.66rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
html[data-ui-theme="nova"] .wb-eyebrow i{width:6px;height:6px;border-radius:2px;background:var(--green);box-shadow:0 0 0 2px var(--green-subtle)}
html[data-ui-theme="nova"] .wb-hero h2{margin:4px 0 2px;font-size:1.2rem;line-height:1.2;letter-spacing:-.03em;font-weight:700;color:var(--ink)}
html[data-ui-theme="nova"] .wb-hero p{margin:0;color:var(--ink-secondary);font-size:.8rem;line-height:1.4}
html[data-ui-theme="nova"] .wb-hero-meta{display:flex;align-items:center;gap:8px;font-size:.72rem;color:var(--muted);flex-shrink:0}
html[data-ui-theme="nova"] .wb-hero-tag{display:inline-flex;align-items:center;gap:5px;padding:3px 8px;border-radius:var(--radius-xs);background:var(--bg-subtle);border:1px solid var(--line);color:var(--ink-secondary);font:600 .7rem var(--font-mono)}
html[data-ui-theme="nova"] .wb-metric-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
html[data-ui-theme="nova"] .wb-metric{display:flex;flex-direction:column;justify-content:space-between;min-height:114px;padding:16px 18px;border:1px solid var(--line);border-radius:var(--radius-md);background:var(--surface);box-shadow:var(--card-highlight);transition:all var(--motion-fast) var(--ease-standard);position:relative;overflow:hidden}
html[data-ui-theme="nova"] .wb-metric:hover{border-color:var(--brand);box-shadow:0 0 0 1px var(--brand-glow),var(--card-highlight)}
html[data-ui-theme="nova"] .wb-metric-head{display:flex;justify-content:space-between;align-items:center;width:100%}
html[data-ui-theme="nova"] .wb-metric label{display:block;color:var(--muted);font-size:.68rem;font-weight:700;letter-spacing:.05em;text-transform:uppercase}
html[data-ui-theme="nova"] .wb-metric-tag{padding:2px 7px;border-radius:var(--radius-xs);background:var(--bg-subtle);border:1px solid var(--line);color:var(--muted);font:700 .62rem var(--font-mono);letter-spacing:.02em}
html[data-ui-theme="nova"] .wb-metric-tag.is-live{background:var(--green-subtle);color:var(--green);border-color:rgba(16,185,129,0.3)}
html[data-ui-theme="nova"] .wb-metric strong{display:block;margin:8px 0 6px;color:var(--ink);font:700 1.6rem/1 var(--font-mono);letter-spacing:-.03em}
html[data-ui-theme="nova"] .wb-metric-footer{display:flex;align-items:center;justify-content:space-between;gap:6px;margin-top:auto;font-size:.72rem;color:var(--muted);line-height:1.3}
html[data-ui-theme="nova"] .wb-metric-footer .trend-up{color:var(--green);font-weight:700}
html[data-ui-theme="nova"] .wb-metric-footer .trend-neutral{color:var(--muted)}
html[data-ui-theme="nova"] .wb-content-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(320px,.65fr);gap:16px;align-items:stretch}
html[data-ui-theme="nova"] .wb-panel{min-width:0;padding:18px 20px;border:1px solid var(--line);border-radius:var(--radius-lg);background:var(--surface);box-shadow:var(--card-highlight);display:flex;flex-direction:column}
html[data-ui-theme="nova"] .wb-panel-header{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;margin-bottom:14px;padding-bottom:10px;border-bottom:1px solid var(--line)}
html[data-ui-theme="nova"] .wb-panel-header h3{margin:0;font-size:.92rem;letter-spacing:-.01em;font-weight:700;color:var(--ink)}
html[data-ui-theme="nova"] .wb-panel-header p{margin:2px 0 0;color:var(--muted);font-size:.74rem}
html[data-ui-theme="nova"] .wb-panel-link{display:inline-flex;align-items:center;gap:4px;color:var(--brand-light);font-size:.74rem;font-weight:700;text-decoration:none}
html[data-ui-theme="nova"] .wb-panel-link svg{width:12px;height:12px}
html[data-ui-theme="nova"] .wb-content-grid>main.wb-panel{align-self:start}
html[data-ui-theme="nova"] .wb-collection-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
html[data-ui-theme="nova"] .wb-collection{display:grid;grid-template-columns:26px minmax(0,1fr) 12px;align-items:center;gap:8px;min-width:0;min-height:46px;padding:8px 10px;border:1px solid var(--line);border-radius:var(--radius-md);color:var(--ink);text-decoration:none;background:var(--bg-subtle);box-shadow:var(--card-highlight);transition:all var(--motion-fast) var(--ease-standard)}
html[data-ui-theme="nova"] .wb-collection:hover{background:var(--surface-hover);border-color:var(--brand);box-shadow:0 0 0 1px var(--brand-glow),var(--shadow-xs)}
html[data-ui-theme="nova"] .wb-collection-icon{display:grid;place-items:center;width:26px;height:26px;border-radius:var(--radius-sm);background:var(--surface);border:1px solid var(--line);color:var(--brand-light);flex-shrink:0}
html[data-ui-theme="nova"] .wb-collection-icon svg{width:14px;height:14px}
html[data-ui-theme="nova"] .wb-collection strong{display:block;font-size:.78rem;font-weight:600;color:var(--ink);line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
html[data-ui-theme="nova"] .wb-collection small{display:block;margin-top:2px;color:var(--muted);font-size:.66rem;line-height:1.25;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
html[data-ui-theme="nova"] .wb-collection>svg{width:12px;height:12px;color:var(--muted);transition:transform var(--motion-fast) ease;flex-shrink:0}
html[data-ui-theme="nova"] .wb-collection:hover>svg{color:var(--brand-light);transform:translateX(2px)}
html[data-ui-theme="nova"] .wb-side-stack{display:flex;flex-direction:column;gap:16px;height:100%}
html[data-ui-theme="nova"] .wb-side-stack .wb-panel{flex:1}
html[data-ui-theme="nova"] .wb-action-list{display:grid;gap:6px}
html[data-ui-theme="nova"] .wb-action{display:grid;grid-template-columns:30px 1fr 12px;align-items:center;gap:10px;padding:8px 10px;border-radius:var(--radius-md);border:1px solid transparent;color:var(--ink);text-decoration:none;transition:all var(--motion-fast) var(--ease-standard)}
html[data-ui-theme="nova"] .wb-action:hover{background:var(--surface-hover);border-color:var(--line)}
html[data-ui-theme="nova"] .wb-action-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:var(--radius-sm);background:var(--bg-subtle);border:1px solid var(--line);color:var(--brand-light);flex-shrink:0}
html[data-ui-theme="nova"] .wb-action-icon svg{width:15px;height:15px}
html[data-ui-theme="nova"] .wb-action strong{display:block;font-size:.78rem;font-weight:600;color:var(--ink)}
html[data-ui-theme="nova"] .wb-action small{display:block;margin-top:1px;color:var(--muted);font-size:.68rem}
html[data-ui-theme="nova"] .wb-action>svg{width:12px;height:12px;color:var(--muted);transition:transform var(--motion-fast) ease;flex-shrink:0}
html[data-ui-theme="nova"] .wb-action:hover>svg{color:var(--brand-light);transform:translateX(2px)}
html[data-ui-theme="nova"] .wb-health-list{display:grid;gap:8px;margin:0;padding:0;list-style:none}
html[data-ui-theme="nova"] .wb-health-list li{display:flex;justify-content:space-between;align-items:center;gap:10px;padding-bottom:7px;border-bottom:1px solid var(--line);font-size:.76rem}
html[data-ui-theme="nova"] .wb-health-list li:last-child{padding-bottom:0;border-bottom:0}
html[data-ui-theme="nova"] .wb-health-list span{color:var(--muted)}
html[data-ui-theme="nova"] .wb-health-list strong{color:var(--ink);font-size:.76rem;text-align:right;font-family:var(--font-mono)}
html[data-ui-theme="nova"] .wb-health-state{display:inline-flex;align-items:center;gap:5px;color:var(--green);font-size:.68rem;font-weight:700;padding:2px 7px;border-radius:var(--radius-sm);background:var(--green-subtle);border:1px solid rgba(16,185,129,.25)}
html[data-ui-theme="nova"] .wb-health-state i{width:5px;height:5px;border-radius:1px;background:var(--green)}
html[data-ui-theme="nova"] .wb-empty{padding:14px;border:1px dashed var(--line);border-radius:var(--radius-md);color:var(--muted);font-size:.75rem;text-align:center}
@media(max-width:1000px){.wb-content-grid{grid-template-columns:1fr}}
@media(max-width:1100px){html[data-ui-theme="nova"] .wb-collection-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:700px){html[data-ui-theme="nova"] .wb-command-row{align-items:flex-start;flex-direction:column}html[data-ui-theme="nova"] .wb-command-actions{width:100%}html[data-ui-theme="nova"] .wb-command-actions .button{flex:1;justify-content:center}html[data-ui-theme="nova"] .wb-metric-strip{grid-template-columns:repeat(2,minmax(0,1fr))}html[data-ui-theme="nova"] .wb-collection-grid{grid-template-columns:1fr}html[data-ui-theme="nova"] .wb-panel{padding:14px}}
@media(prefers-reduced-motion:reduce){html[data-ui-theme="nova"] .wb-metric,html[data-ui-theme="nova"] .wb-collection,html[data-ui-theme="nova"] .wb-action{transition:none}}`
